import re

# We need to inject the seoContent and extend the faqs.
# Instead of doing complex string replacement, I will generate a small python script that parses the TS ast... wait, no.
# I can do regex replacements easily if I match the slugs.

services_updates = {
    'obra-nueva-valencia': {
        'content': content_obra_nueva,
        'new_faqs': new_faqs_obra_nueva
    },
    'reformas-integrales-valencia': {
        'content': content_reformas,
        'new_faqs': new_faqs_reformas
    },
    'rehabilitacion-edificios-valencia': {
        'content': content_rehabilitacion,
        'new_faqs': new_faqs_rehabilitacion
    }
}

for slug, data in services_updates.items():
    # 1. Add seoContent
    # Find where the service object starts
    pattern = r"(slug:\s*'" + slug + r"'.*?faqs:\s*\[)(.*?)(\]\s*\n\s*\})"
    
    match = re.search(pattern, constants_data, re.DOTALL)
    if match:
        existing_faqs = match.group(2)
        
        # Build new faqs string
        new_faqs_str = ""
        for faq in data['new_faqs']:
            new_faqs_str += f",\n      {{\n        q: '{faq['q']}',\n        a: '{faq['a']}'\n      }}"
            
        modified_faqs = existing_faqs + new_faqs_str
        
        # Escape backticks in content
        safe_content = data['content'].replace('`', '\\`')
        
        replacement = match.group(1) + modified_faqs + "],\n    seoContent: `" + safe_content + "`\n  }"
        
        constants_data = constants_data.replace(match.group(0), replacement)

with open('/Users/jorge/Desktop/Antigravity/constructora-valencia/lib/constants.ts', 'w', encoding='utf-8') as f:
    f.write(constants_data)

print("Updated constants.ts with SEO content for 3 services.")
